contracts/VehicleConsent.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VehicleNFT.sol";

/**
 * @title VehicleConsent
 * @notice จัดการสิทธิ์การอ่านข้อมูล (Consent / Permission)
 *
 * On-chain data:
 *   - grantTo (hash DID), scopeMask, expiresAt, nonce, grantHash
 *   - writerRoleAllowed, writerAllowlist
 *
 * Off-chain data (DB):
 *   - granteeIdentity (DID, email), scope[], auditLog[]
 *   - PII (ชื่อ/ที่อยู่/โทร)
 */
contract VehicleConsent {
    // ─── Structs ─────────────────────────────────────────────
    struct Grant {
        bytes32 granteeDid;     // keccak256(DID)
        uint64  scopeMask;      // bitmask ของสิทธิ์อ่าน
        uint64  expiresAt;      // unix timestamp หมดอายุ
        uint64  nonce;          // ป้องกัน replay
        bool    singleUse;      // ใช้ได้ครั้งเดียว
        bool    used;           // ใช้แล้วหรือยัง (สำหรับ singleUse)
        bool    revoked;        // ถูก revoke
    }

    // ─── Scope Bitmask Constants ─────────────────────────────
    uint64 public constant SCOPE_VEHICLE_IDENTITY    = 1 << 0;
    uint64 public constant SCOPE_MAINTENANCE_FULL    = 1 << 1;
    uint64 public constant SCOPE_MAINTENANCE_SUMMARY = 1 << 2;
    uint64 public constant SCOPE_CLAIMS_FULL         = 1 << 3;
    uint64 public constant SCOPE_CLAIMS_SUMMARY      = 1 << 4;
    uint64 public constant SCOPE_OWNERSHIP_HISTORY   = 1 << 5;
    uint64 public constant SCOPE_INSPECTION_HISTORY  = 1 << 6;
    uint64 public constant SCOPE_ODOMETER_TREND      = 1 << 7;
    uint64 public constant SCOPE_PII                 = 1 << 8;

    // ─── State ───────────────────────────────────────────────
    VehicleNFT public vehicleNFT;

    /// tokenId → grantHash → Grant
    mapping(uint256 => mapping(bytes32 => Grant)) public grants;

    /// tokenId → granted DID hashes (for enumeration)
    mapping(uint256 => bytes32[]) private _grantKeys;

    // ─── Events ──────────────────────────────────────────────
    event ConsentGranted(
        uint256 indexed tokenId,
        address indexed owner,
        bytes32 granteeDid,
        uint64  scopeMask,
        uint64  expiresAt,
        uint64  nonce,
        bool    singleUse,
        bytes32 grantHash
    );

    event ConsentRevoked(
        uint256 indexed tokenId,
        bytes32 grantHash
    );

    event ConsentUsed(
        uint256 indexed tokenId,
        bytes32 grantHash,
        address accessor
    );

    // ─── Constructor ─────────────────────────────────────────
    constructor(address _vehicleNFT) {
        vehicleNFT = VehicleNFT(_vehicleNFT);
    }

    // ─── Grant ───────────────────────────────────────────────
    /**
     * @notice เจ้าของรถให้สิทธิ์อ่านข้อมูลแก่บุคคล/องค์กร
     */
    function grantConsent(
        uint256 tokenId,
        bytes32 granteeDid,
        uint64  scopeMask,
        uint64  expiresAt,
        bool    singleUse,
        uint64  nonce
    ) external returns (bytes32 grantHash) {
        require(vehicleNFT.ownerOf(tokenId) == msg.sender, "Not vehicle owner");
        require(expiresAt > block.timestamp, "Already expired");
        require(scopeMask > 0, "Empty scope");

        grantHash = keccak256(abi.encode(
            tokenId, granteeDid, scopeMask, expiresAt, singleUse, nonce
        ));

        require(grants[tokenId][grantHash].nonce == 0, "Grant already exists");

        grants[tokenId][grantHash] = Grant({
            granteeDid: granteeDid,
            scopeMask: scopeMask,
            expiresAt: expiresAt,
            nonce: nonce,
            singleUse: singleUse,
            used: false,
            revoked: false
        });

        _grantKeys[tokenId].push(grantHash);

        emit ConsentGranted(
            tokenId, msg.sender, granteeDid, scopeMask,
            expiresAt, nonce, singleUse, grantHash
        );
    }

    // ─── Revoke ──────────────────────────────────────────────
    /**
     * @notice ถอนสิทธิ์
     */
    function revokeConsent(uint256 tokenId, bytes32 grantHash) external {
        require(vehicleNFT.ownerOf(tokenId) == msg.sender, "Not vehicle owner");
        require(!grants[tokenId][grantHash].revoked, "Already revoked");

        grants[tokenId][grantHash].revoked = true;
        emit ConsentRevoked(tokenId, grantHash);
    }

    // ─── Verify (called by backend / other contracts) ────────
    /**
     * @notice ตรวจสอบว่า grant ยัง valid อยู่ไหม
     * @return valid   true ถ้าใช้ได้
     * @return scope   scopeMask ของ grant
     */
    function verifyConsent(
        uint256 tokenId,
        bytes32 grantHash
    ) external returns (bool valid, uint64 scope) {
        Grant storage g = grants[tokenId][grantHash];

        if (g.nonce == 0 || g.revoked) return (false, 0);
        if (block.timestamp > g.expiresAt) return (false, 0);
        if (g.singleUse && g.used) return (false, 0);

        // Mark used
        if (g.singleUse) {
            g.used = true;
        }

        emit ConsentUsed(tokenId, grantHash, msg.sender);
        return (true, g.scopeMask);
    }

    // ─── View ────────────────────────────────────────────────
    function getGrant(uint256 tokenId, bytes32 grantHash) external view returns (Grant memory) {
        return grants[tokenId][grantHash];
    }

    function isGrantValid(uint256 tokenId, bytes32 grantHash) external view returns (bool) {
        Grant storage g = grants[tokenId][grantHash];
        if (g.nonce == 0 || g.revoked) return false;
        if (block.timestamp > g.expiresAt) return false;
        if (g.singleUse && g.used) return false;
        return true;
    }
}

contracts/VehicleLien.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./VehicleNFT.sol";

/**
 * @title VehicleLien
 * @notice ไฟแนนซ์/สินเชื่อ – ภาระผูกพัน (Lien) + Escrow สำหรับ P2P
 *
 * On-chain data:
 *   Lien: lender, lienStatus, transferLocked, loanContractHash,
 *         startedAt, releaseConditionHash
 *   Escrow: buyer, seller, conditionsMask, depositAsset, depositAmount, state
 *
 * Off-chain data (DB):
 *   loanAccountNo, principal, interestRate, termMonths, contractDoc,
 *   borrowerKYC, escrow deal terms ฯลฯ
 */
contract VehicleLien is AccessControl, ReentrancyGuard {
    // ─── Roles ───────────────────────────────────────────────
    bytes32 public constant FINANCE_ROLE = keccak256("FINANCE_ROLE");

    // ─── Enums ───────────────────────────────────────────────
    enum LienStatus  { None, Active, Released, Defaulted }
    enum EscrowState { Created, Funded, Released, Cancelled }

    // ─── Structs ─────────────────────────────────────────────
    struct Lien {
        address   lender;
        LienStatus status;
        bytes32   loanContractHash;
        uint64    startedAt;
        bytes32   releaseConditionHash;
    }

    struct Escrow {
        bytes32     escrowId;
        uint256     tokenId;
        address     buyer;
        address     seller;
        uint64      conditionsMask;   // bitmask: 1=payment_confirmed, 2=lien_released
        address     depositAsset;     // ERC20 address, หรือ address(0) = native coin
        uint256     depositAmount;
        EscrowState state;
    }

    // ─── Condition Bitmask ───────────────────────────────────
    uint64 public constant COND_PAYMENT_CONFIRMED = 1 << 0;
    uint64 public constant COND_LIEN_RELEASED     = 1 << 1;

    // ─── State ───────────────────────────────────────────────
    VehicleNFT public vehicleNFT;

    mapping(uint256 => Lien)    public liens;
    mapping(bytes32 => Escrow)  public escrows;

    /// ติดตาม conditions ที่ fulfill แล้ว
    mapping(bytes32 => uint64)  public fulfilledConditions;

    // ─── Events ──────────────────────────────────────────────
    event LienCreated(
        uint256 indexed tokenId,
        address indexed lender,
        bytes32 loanContractHash,
        uint64  startedAt
    );

    event LienStatusChanged(
        uint256 indexed tokenId,
        LienStatus newStatus
    );

    event EscrowCreated(
        bytes32 indexed escrowId,
        uint256 indexed tokenId,
        address buyer,
        address seller,
        uint64  conditionsMask,
        address depositAsset,
        uint256 depositAmount
    );

    event EscrowFunded(bytes32 indexed escrowId, uint256 amount);

    event EscrowReleased(bytes32 indexed escrowId, uint256 tokenId);

    event EscrowCancelled(bytes32 indexed escrowId);

    event ConditionFulfilled(bytes32 indexed escrowId, uint64 condition);

    // ─── Constructor ─────────────────────────────────────────
    constructor(address _vehicleNFT) {
        vehicleNFT = VehicleNFT(_vehicleNFT);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    // ─── Lien Management ─────────────────────────────────────
    /**
     * @notice สร้างภาระผูกพัน + ล็อกการโอน
     */
    function createLien(
        uint256 tokenId,
        bytes32 loanContractHash,
        bytes32 releaseConditionHash
    ) external onlyRole(FINANCE_ROLE) {
        require(liens[tokenId].status == LienStatus.None, "Lien already exists");

        liens[tokenId] = Lien({
            lender: msg.sender,
            status: LienStatus.Active,
            loanContractHash: loanContractHash,
            startedAt: uint64(block.timestamp),
            releaseConditionHash: releaseConditionHash
        });

        vehicleNFT.setTransferLock(tokenId, true);

        emit LienCreated(tokenId, msg.sender, loanContractHash, uint64(block.timestamp));
    }

    /**
     * @notice ปลดภาระผูกพัน + ปลดล็อกการโอน
     */
    function releaseLien(uint256 tokenId) external {
        Lien storage lien = liens[tokenId];
        require(lien.status == LienStatus.Active, "No active lien");
        require(
            msg.sender == lien.lender || hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "Not lender"
        );

        lien.status = LienStatus.Released;
        vehicleNFT.setTransferLock(tokenId, false);

        emit LienStatusChanged(tokenId, LienStatus.Released);
    }

    /**
     * @notice ตั้งสถานะ defaulted
     */
    function markDefault(uint256 tokenId) external {
        Lien storage lien = liens[tokenId];
        require(lien.status == LienStatus.Active, "No active lien");
        require(
            msg.sender == lien.lender || hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "Not lender"
        );

        lien.status = LienStatus.Defaulted;
        emit LienStatusChanged(tokenId, LienStatus.Defaulted);
    }

    // ─── Escrow (P2P with conditions) ────────────────────────
    /**
     * @notice สร้าง escrow สำหรับการซื้อขายแบบมีเงื่อนไข
     */
    function createEscrow(
        bytes32 escrowId,
        uint256 tokenId,
        address buyer,
        uint64  conditionsMask,
        address depositAsset,
        uint256 depositAmount
    ) external {
        address seller = vehicleNFT.ownerOf(tokenId);
        require(msg.sender == seller, "Not vehicle owner");
        require(escrows[escrowId].tokenId == 0, "Escrow ID exists");

        escrows[escrowId] = Escrow({
            escrowId: escrowId,
            tokenId: tokenId,
            buyer: buyer,
            seller: seller,
            conditionsMask: conditionsMask,
            depositAsset: depositAsset,
            depositAmount: depositAmount,
            state: EscrowState.Created
        });

        emit EscrowCreated(
            escrowId, tokenId, buyer, seller,
            conditionsMask, depositAsset, depositAmount
        );
    }

    /**
     * @notice ผู้ซื้อวางเงินเข้า escrow (native coin)
     */
    function fundEscrowNative(bytes32 escrowId) external payable nonReentrant {
        Escrow storage esc = escrows[escrowId];
        require(esc.state == EscrowState.Created, "Not in created state");
        require(msg.sender == esc.buyer, "Not buyer");
        require(esc.depositAsset == address(0), "Use ERC20 fund");
        require(msg.value == esc.depositAmount, "Wrong amount");

        esc.state = EscrowState.Funded;
        emit EscrowFunded(escrowId, msg.value);
    }

    /**
     * @notice ผู้ซื้อวางเงินเข้า escrow (ERC20)
     */
    function fundEscrowERC20(bytes32 escrowId) external nonReentrant {
        Escrow storage esc = escrows[escrowId];
        require(esc.state == EscrowState.Created, "Not in created state");
        require(msg.sender == esc.buyer, "Not buyer");
        require(esc.depositAsset != address(0), "Use native fund");

        IERC20(esc.depositAsset).transferFrom(msg.sender, address(this), esc.depositAmount);

        esc.state = EscrowState.Funded;
        emit EscrowFunded(escrowId, esc.depositAmount);
    }

    /**
     * @notice Fulfill เงื่อนไข (เรียกโดย finance หรือ seller)
     */
    function fulfillCondition(bytes32 escrowId, uint64 condition) external {
        Escrow storage esc = escrows[escrowId];
        require(esc.state == EscrowState.Funded, "Not funded");

        // ใครมีสิทธิ์ fulfill?
        require(
            msg.sender == esc.seller ||
            msg.sender == esc.buyer ||
            hasRole(FINANCE_ROLE, msg.sender) ||
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "Not authorized"
        );

        fulfilledConditions[escrowId] |= condition;
        emit ConditionFulfilled(escrowId, condition);

        // ตรวจว่าครบทุก condition หรือยัง → auto release
        if ((fulfilledConditions[escrowId] & esc.conditionsMask) == esc.conditionsMask) {
            _releaseEscrow(escrowId);
        }
    }

    /**
     * @notice ยกเลิก escrow (คืนเงินผู้ซื้อ)
     */
    function cancelEscrow(bytes32 escrowId) external nonReentrant {
        Escrow storage esc = escrows[escrowId];
        require(
            esc.state == EscrowState.Created || esc.state == EscrowState.Funded,
            "Cannot cancel"
        );
        require(
            msg.sender == esc.seller || msg.sender == esc.buyer,
            "Not party"
        );

        if (esc.state == EscrowState.Funded) {
            // คืนเงินผู้ซื้อ
            if (esc.depositAsset == address(0)) {
                payable(esc.buyer).transfer(esc.depositAmount);
            } else {
                IERC20(esc.depositAsset).transfer(esc.buyer, esc.depositAmount);
            }
        }

        esc.state = EscrowState.Cancelled;
        emit EscrowCancelled(escrowId);
    }

    // ─── Internal ────────────────────────────────────────────
    function _releaseEscrow(bytes32 escrowId) internal nonReentrant {
        Escrow storage esc = escrows[escrowId];
        esc.state = EscrowState.Released;

        // โอนเงินให้ seller
        if (esc.depositAsset == address(0)) {
            payable(esc.seller).transfer(esc.depositAmount);
        } else {
            IERC20(esc.depositAsset).transfer(esc.seller, esc.depositAmount);
        }

        emit EscrowReleased(escrowId, esc.tokenId);
    }

    // ─── View ────────────────────────────────────────────────
    function getLien(uint256 tokenId) external view returns (Lien memory) {
        return liens[tokenId];
    }

    function getEscrow(bytes32 escrowId) external view returns (Escrow memory) {
        return escrows[escrowId];
    }

    function isLienActive(uint256 tokenId) external view returns (bool) {
        return liens[tokenId].status == LienStatus.Active;
    }
}

contracts/VehicleLifecycle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "./VehicleNFT.sol";

/**
 * @title VehicleLifecycle
 * @notice บันทึก event ตลอดชีวิตรถ:
 *         ซ่อมบำรุง, เปลี่ยนอะไหล่, ประกันภัย, เคลม, การโอน, disclosure
 *
 * On-chain: เฉพาะ hash + metadata ที่ต้อง verify
 * Off-chain: รายละเอียดทั้งหมดใน DB / IPFS
 */
contract VehicleLifecycle is AccessControl {
    // ─── Roles ───────────────────────────────────────────────
    bytes32 public constant DEALER_ROLE    = keccak256("DEALER_ROLE");
    bytes32 public constant WORKSHOP_ROLE  = keccak256("WORKSHOP_ROLE");
    bytes32 public constant INSURER_ROLE   = keccak256("INSURER_ROLE");

    // ─── Enums ───────────────────────────────────────────────
    enum AccidentSeverity { None, Minor, Major, Structural }
    enum InsuranceAction  { New, Renew, Change, Cancel }
    enum ClaimStatus      { Filed, Estimating, Approved, Repairing, Closed, Rejected }
    enum ClaimSeverity    { Minor, Major, Structural, TotalLoss }

    // ─── State ───────────────────────────────────────────────
    VehicleNFT public vehicleNFT;

    /// tokenId → consent address → scope mask (delegated write)
    mapping(uint256 => mapping(address => uint64)) public writeConsents;

    // ─── Events ──────────────────────────────────────────────

    // Ownership / Transfer
    event OwnershipTransferred(
        uint256 indexed tokenId,
        address indexed from,
        address indexed to,
        uint8   reason,           // TransferReason enum value
        bytes32 saleContractHash,
        bytes32 buyerOwnerId,     // keccak256(DID)
        uint64  deliveryAt,
        bytes32 paymentRefHash
    );

    // Disclosure (ย้อมแมว prevention)
    event DisclosureRecorded(
        uint256 indexed tokenId,
        address seller,
        bytes32 buyerOwnerId,
        uint64  disclosedItemsMask,
        bytes32 ackHash,
        uint64  signedAt
    );

    // Maintenance
    event MaintenanceLogged(
        uint256 indexed tokenId,
        address indexed workshop,
        bytes32 writeConsentRefHash,
        uint32  mileageKm,
        bytes32 maintenanceHash,
        bytes32 partsHash,
        uint8   accidentSeverity,
        uint64  occurredAt
    );

    // Insurance Policy
    event InsurancePolicyEvent(
        uint256 indexed tokenId,
        address indexed insurer,
        bytes32 policyNoHash,
        InsuranceAction action,
        uint64  validFrom,
        uint64  validTo,
        bytes32 coverageHash
    );

    // Insurance Claim
    event ClaimFiled(
        uint256 indexed tokenId,
        bytes32 claimNoHash,
        uint64  filedAt,
        bytes32[] evidenceHashes,
        ClaimSeverity severity
    );

    event ClaimStatusUpdated(
        uint256 indexed tokenId,
        bytes32 claimNoHash,
        ClaimStatus newStatus
    );

    // Generic event (catch-all สำหรับ event อื่น ๆ)
    event GenericEvent(
        uint256 indexed tokenId,
        uint32  eventType,
        address actor,
        uint64  occurredAt,
        bytes32 payloadHash,
        bytes32 evidenceHash
    );

    // ─── Constructor ─────────────────────────────────────────
    constructor(address _vehicleNFT) {
        vehicleNFT = VehicleNFT(_vehicleNFT);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    // ─── Modifiers ───────────────────────────────────────────
    modifier vehicleExists(uint256 tokenId) {
        require(vehicleNFT.ownerOf(tokenId) != address(0), "Vehicle does not exist");
        _;
    }

    modifier onlyVehicleOwner(uint256 tokenId) {
        require(vehicleNFT.ownerOf(tokenId) == msg.sender, "Not vehicle owner");
        _;
    }

    // ─── Consent (Owner → Workshop) ──────────────────────────
    /**
     * @notice เจ้าของอนุญาตให้อู่เขียน record
     * @param scopeMask  bitmask สิทธิ์: 1=maintenance, 2=odometer, 4=parts, 8=accident_flag
     */
    function grantWriteConsent(
        uint256 tokenId,
        address workshop,
        uint64  scopeMask,
        uint64  expiresAt,
        bool    singleUse,
        uint64  nonce
    ) external onlyVehicleOwner(tokenId) {
        // encode expiry + singleUse + nonce into scope
        writeConsents[tokenId][workshop] = scopeMask;
        // emit for off-chain indexing
        emit GenericEvent(
            tokenId,
            100, // CONSENT_GRANTED type
            msg.sender,
            uint64(block.timestamp),
            keccak256(abi.encode(workshop, scopeMask, expiresAt, singleUse, nonce)),
            bytes32(0)
        );
    }

    function revokeWriteConsent(uint256 tokenId, address workshop)
        external onlyVehicleOwner(tokenId)
    {
        delete writeConsents[tokenId][workshop];
        emit GenericEvent(
            tokenId,
            101, // CONSENT_REVOKED type
            msg.sender,
            uint64(block.timestamp),
            keccak256(abi.encode(workshop)),
            bytes32(0)
        );
    }

    // ─── Maintenance Log ─────────────────────────────────────
    /**
     * @notice อู่บันทึกประวัติซ่อม (ต้องมี consent จากเจ้าของ)
     */
    function logMaintenance(
        uint256 tokenId,
        bytes32 writeConsentRefHash,
        uint32  mileageKm,
        bytes32 maintenanceHash,
        bytes32 partsHash,
        uint8   accidentSeverity,
        uint64  occurredAt
    ) external onlyRole(WORKSHOP_ROLE) vehicleExists(tokenId) {
        require(writeConsents[tokenId][msg.sender] > 0, "No write consent");
        require(accidentSeverity <= 3, "Invalid severity");

        emit MaintenanceLogged(
            tokenId,
            msg.sender,
            writeConsentRefHash,
            mileageKm,
            maintenanceHash,
            partsHash,
            accidentSeverity,
            occurredAt
        );
    }

    // ─── Ownership Transfer ──────────────────────────────────
    /**
     * @notice บันทึก event การโอนกรรมสิทธิ์ (เรียกพร้อมกับ ERC721 transfer)
     * @param reason  0=inventory_transfer, 1=first_sale, 2=resale, 3=trade_in
     */
    function recordTransfer(
        uint256 tokenId,
        address to,
        uint8   reason,
        bytes32 saleContractHash,
        bytes32 buyerOwnerId,
        bytes32 paymentRefHash
    ) external vehicleExists(tokenId) {
        address from = vehicleNFT.ownerOf(tokenId);
        require(
            msg.sender == from ||
            hasRole(DEALER_ROLE, msg.sender) ||
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "Not authorized"
        );

        emit OwnershipTransferred(
            tokenId,
            from,
            to,
            reason,
            saleContractHash,
            buyerOwnerId,
            uint64(block.timestamp),
            paymentRefHash
        );
    }

    // ─── Disclosure ──────────────────────────────────────────
    /**
     * @notice บันทึกการเปิดเผยข้อมูลสำคัญก่อนขาย
     */
    function recordDisclosure(
        uint256 tokenId,
        bytes32 buyerOwnerId,
        uint64  disclosedItemsMask,
        bytes32 ackHash
    ) external vehicleExists(tokenId) {
        address owner = vehicleNFT.ownerOf(tokenId);
        require(
            msg.sender == owner || hasRole(DEALER_ROLE, msg.sender),
            "Not seller"
        );

        emit DisclosureRecorded(
            tokenId,
            msg.sender,
            buyerOwnerId,
            disclosedItemsMask,
            ackHash,
            uint64(block.timestamp)
        );
    }

    // ─── Insurance Policy ────────────────────────────────────
    /**
     * @notice บันทึก event กรมธรรม์ประกันภัย
     */
    function recordInsurancePolicy(
        uint256         tokenId,
        bytes32         policyNoHash,
        InsuranceAction action,
        uint64          validFrom,
        uint64          validTo,
        bytes32         coverageHash
    ) external onlyRole(INSURER_ROLE) vehicleExists(tokenId) {
        emit InsurancePolicyEvent(
            tokenId,
            msg.sender,
            policyNoHash,
            action,
            validFrom,
            validTo,
            coverageHash
        );
    }

    // ─── Insurance Claim ─────────────────────────────────────
    /**
     * @notice เปิดเคลมประกัน
     */
    function fileClaim(
        uint256       tokenId,
        bytes32       claimNoHash,
        bytes32[]     calldata evidenceHashes,
        ClaimSeverity severity
    ) external onlyRole(INSURER_ROLE) vehicleExists(tokenId) {
        emit ClaimFiled(
            tokenId,
            claimNoHash,
            uint64(block.timestamp),
            evidenceHashes,
            severity
        );
    }

    /**
     * @notice อัปเดตสถานะเคลม
     */
    function updateClaimStatus(
        uint256     tokenId,
        bytes32     claimNoHash,
        ClaimStatus newStatus
    ) external onlyRole(INSURER_ROLE) vehicleExists(tokenId) {
        emit ClaimStatusUpdated(tokenId, claimNoHash, newStatus);
    }

    // ─── Generic Event ───────────────────────────────────────
    /**
     * @notice บันทึก event ทั่วไป (สำหรับ event type ที่ไม่มี function เฉพาะ)
     */
    function logEvent(
        uint256 tokenId,
        uint32  eventType,
        uint64  occurredAt,
        bytes32 payloadHash,
        bytes32 evidenceHash
    ) external vehicleExists(tokenId) {
        emit GenericEvent(tokenId, eventType, msg.sender, occurredAt, payloadHash, evidenceHash);
    }
}

contracts/VehicleNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title VehicleNFT
 * @notice Core ERC-721 contract – ตัวตนรถ (Vehicle Identity)
 *
 * On-chain data (ต่อ tokenId):
 *   - vinHash, manufacturerId, manufacturedAt, modelHash, specHash
 *   - transferLocked flag (ควบคุมโดย VehicleRegistry / VehicleLien)
 *
 * Off-chain data (DB):
 *   - vinPlain, modelJson, specJson, manufacturerSignature
 */
contract VehicleNFT is ERC721, AccessControl, ReentrancyGuard {
    // ─── Roles ───────────────────────────────────────────────
    bytes32 public constant MANUFACTURER_ROLE = keccak256("MANUFACTURER_ROLE");
    bytes32 public constant REGISTRY_ROLE     = keccak256("REGISTRY_ROLE");
    bytes32 public constant LIEN_ROLE         = keccak256("LIEN_ROLE");

    // ─── Structs ─────────────────────────────────────────────
    struct VehicleIdentity {
        bytes32 vinHash;
        address manufacturerId;
        uint64  manufacturedAt;
        bytes32 modelHash;
        bytes32 specHash;
    }

    // ─── State ───────────────────────────────────────────────
    uint256 private _nextTokenId;

    /// tokenId → identity
    mapping(uint256 => VehicleIdentity) public vehicles;

    /// ป้องกัน VIN ซ้ำ
    mapping(bytes32 => bool) private _usedVins;

    /// ล็อกการโอน (ตั้งโดย Registry หรือ Lien)
    mapping(uint256 => bool) public transferLocked;

    // ─── Events ──────────────────────────────────────────────
    event VehicleMinted(
        uint256 indexed tokenId,
        bytes32 vinHash,
        address indexed manufacturer,
        uint64  manufacturedAt,
        bytes32 modelHash,
        bytes32 specHash
    );

    event TransferLockChanged(uint256 indexed tokenId, bool locked, address changedBy);

    // ─── Constructor ─────────────────────────────────────────
    constructor() ERC721("VehicleNFT", "VNFT") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MANUFACTURER_ROLE, msg.sender);
    }

    // ─── Mint ────────────────────────────────────────────────
    /**
     * @notice Mint รถใหม่จากโรงงาน
     * @param to          address ที่รับ NFT (อาจเป็น manufacturer เอง)
     * @param vinHash     keccak256(VIN)
     * @param manufacturedAt  unix timestamp วันผลิต
     * @param modelHash   hash ของ model JSON
     * @param specHash    hash ของ spec JSON
     */
    function mintVehicle(
        address to,
        bytes32 vinHash,
        uint64  manufacturedAt,
        bytes32 modelHash,
        bytes32 specHash
    ) external onlyRole(MANUFACTURER_ROLE) returns (uint256 tokenId) {
        require(!_usedVins[vinHash], "VIN already registered");

        tokenId = _nextTokenId++;
        _safeMint(to, tokenId);

        vehicles[tokenId] = VehicleIdentity({
            vinHash: vinHash,
            manufacturerId: msg.sender,
            manufacturedAt: manufacturedAt,
            modelHash: modelHash,
            specHash: specHash
        });

        _usedVins[vinHash] = true;

        emit VehicleMinted(tokenId, vinHash, msg.sender, manufacturedAt, modelHash, specHash);
    }

    // ─── Transfer Lock ───────────────────────────────────────
    /**
     * @notice ตั้ง/ปลด transfer lock (เรียกจาก Registry หรือ Lien contract)
     */
    function setTransferLock(uint256 tokenId, bool locked)
        external
    {
        require(
            hasRole(REGISTRY_ROLE, msg.sender) || hasRole(LIEN_ROLE, msg.sender),
            "Not authorized to change lock"
        );
        transferLocked[tokenId] = locked;
        emit TransferLockChanged(tokenId, locked, msg.sender);
    }

    // ─── Transfer Override ───────────────────────────────────
    /**
     * @dev ตรวจสอบ transferLocked ก่อนทุกการโอน
     */
    function _update(address to, uint256 tokenId, address auth)
        internal
        override
        returns (address)
    {
        // อนุญาต mint (from == 0) โดยไม่ต้องเช็ค lock
        address from = _ownerOf(tokenId);
        if (from != address(0)) {
            require(!transferLocked[tokenId], "Transfer is locked");
        }
        return super._update(to, tokenId, auth);
    }

    // ─── View ────────────────────────────────────────────────
    function getVehicle(uint256 tokenId) external view returns (VehicleIdentity memory) {
        require(_ownerOf(tokenId) != address(0), "Vehicle does not exist");
        return vehicles[tokenId];
    }

    function isVinUsed(bytes32 vinHash) external view returns (bool) {
        return _usedVins[vinHash];
    }

    // ─── ERC-165 ─────────────────────────────────────────────
    function supportsInterface(bytes4 interfaceId)
        public view override(ERC721, AccessControl) returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/VehicleRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "./VehicleNFT.sol";

/**
 * @title VehicleRegistry
 * @notice กรมการขนส่งทางบก (DLT) – จดทะเบียน, ป้ายทะเบียน, ภาษี, ธงสถานะ
 *
 * On-chain data:
 *   - Registration: isRegistered, registeredAt, dltOfficer, greenBookNoHash, docHash, status
 *   - Plate: plateNoHash, provinceCode, eventType, docHash, effectiveAt
 *   - Tax: taxYear, paidAt, validUntil, receiptHash, status
 *   - Flags: bitmask (stolen/seized/flood/totalLoss/scrapped/...)
 *
 * Off-chain data (DB):
 *   - greenBookNoPlain, plateNoPlain, ownerPII, เอกสาร CID/URL, amount ฯลฯ
 */
contract VehicleRegistry is AccessControl {
    // ─── Roles ───────────────────────────────────────────────
    bytes32 public constant DLT_OFFICER_ROLE    = keccak256("DLT_OFFICER_ROLE");
    bytes32 public constant INSPECTOR_ROLE      = keccak256("INSPECTOR_ROLE");

    // ─── Flag Bitmask Constants ──────────────────────────────
    uint64 public constant FLAG_STOLEN          = 1 << 0;
    uint64 public constant FLAG_SEIZED          = 1 << 1;
    uint64 public constant FLAG_MAJOR_ACCIDENT  = 1 << 2;
    uint64 public constant FLAG_FLOOD           = 1 << 3;
    uint64 public constant FLAG_TOTAL_LOSS      = 1 << 4;
    uint64 public constant FLAG_SCRAPPED        = 1 << 5;
    uint64 public constant FLAG_REG_CANCELLED   = 1 << 6;

    // ─── Enums ───────────────────────────────────────────────
    enum RegStatus   { Unregistered, Registered, Suspended, Cancelled }
    enum PlateEvent  { Issue, Change, Lost }
    enum TaxStatus   { Paid, Unpaid, Overdue }

    // ─── Structs ─────────────────────────────────────────────
    struct RegistrationData {
        bool      isRegistered;
        uint64    registeredAt;
        address   dltOfficer;
        bytes32   greenBookNoHash;
        bytes32   registrationDocHash;
        RegStatus status;
    }

    // ─── State ───────────────────────────────────────────────
    VehicleNFT public vehicleNFT;

    mapping(uint256 => RegistrationData) public registrations;
    mapping(uint256 => uint64)           public flags;

    /// cache ผลตรวจสภาพล่าสุดที่ผ่าน (ใช้ validate ก่อนต่อภาษี)
    mapping(uint256 => uint64) public lastInspectionPassAt;
    /// อายุสูงสุดของผลตรวจสภาพ (seconds) – ตั้งค่าได้โดย admin
    uint64 public inspectionMaxAge = 365 days;

    // ─── Events ──────────────────────────────────────────────
    event VehicleRegistered(
        uint256 indexed tokenId,
        address dltOfficer,
        bytes32 greenBookNoHash,
        bytes32 registrationDocHash
    );

    event RegistrationStatusChanged(uint256 indexed tokenId, RegStatus newStatus);

    event PlateEventRecorded(
        uint256 indexed tokenId,
        bytes32 plateNoHash,
        uint16  provinceCode,
        PlateEvent eventType,
        bytes32 docHash,
        uint64  effectiveAt
    );

    event TaxPaid(
        uint256 indexed tokenId,
        uint16  taxYear,
        uint64  paidAt,
        uint64  validUntil,
        bytes32 receiptHash,
        TaxStatus status
    );

    event FlagUpdated(
        uint256 indexed tokenId,
        uint64  newFlags,
        address source,
        bytes32 refHash
    );

    event InspectionRecorded(
        uint256 indexed tokenId,
        address station,
        uint8   result,      // 0 = fail, 1 = pass
        bytes32 metricsHash,
        bytes32 certHash,
        uint64  issuedAt
    );

    // ─── Constructor ─────────────────────────────────────────
    constructor(address _vehicleNFT) {
        vehicleNFT = VehicleNFT(_vehicleNFT);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    // ─── Modifiers ───────────────────────────────────────────
    modifier vehicleExists(uint256 tokenId) {
        require(vehicleNFT.ownerOf(tokenId) != address(0), "Vehicle does not exist");
        _;
    }

    // ─── Registration ────────────────────────────────────────
    /**
     * @notice จดทะเบียนรถ (ครั้งแรก)
     */
    function registerVehicle(
        uint256 tokenId,
        bytes32 greenBookNoHash,
        bytes32 registrationDocHash
    ) external onlyRole(DLT_OFFICER_ROLE) vehicleExists(tokenId) {
        require(!registrations[tokenId].isRegistered, "Already registered");

        registrations[tokenId] = RegistrationData({
            isRegistered: true,
            registeredAt: uint64(block.timestamp),
            dltOfficer: msg.sender,
            greenBookNoHash: greenBookNoHash,
            registrationDocHash: registrationDocHash,
            status: RegStatus.Registered
        });

        emit VehicleRegistered(tokenId, msg.sender, greenBookNoHash, registrationDocHash);
    }

    /**
     * @notice เปลี่ยนสถานะการจดทะเบียน (suspend/cancel/re-register)
     */
    function setRegistrationStatus(uint256 tokenId, RegStatus newStatus)
        external onlyRole(DLT_OFFICER_ROLE) vehicleExists(tokenId)
    {
        registrations[tokenId].status = newStatus;
        emit RegistrationStatusChanged(tokenId, newStatus);

        // ถ้ายกเลิก → ล็อกการโอน + ติด flag
        if (newStatus == RegStatus.Cancelled) {
            vehicleNFT.setTransferLock(tokenId, true);
            _setFlag(tokenId, FLAG_REG_CANCELLED, true, bytes32(0));
        }
    }

    // ─── Plate ───────────────────────────────────────────────
    /**
     * @notice บันทึก event ป้ายทะเบียน (ออก/เปลี่ยน/หาย)
     */
    function recordPlateEvent(
        uint256    tokenId,
        bytes32    plateNoHash,
        uint16     provinceCode,
        PlateEvent eventType,
        bytes32    docHash,
        uint64     effectiveAt
    ) external onlyRole(DLT_OFFICER_ROLE) vehicleExists(tokenId) {
        emit PlateEventRecorded(tokenId, plateNoHash, provinceCode, eventType, docHash, effectiveAt);
    }

    // ─── Tax ─────────────────────────────────────────────────
    /**
     * @notice บันทึกการชำระภาษีประจำปี
     * @dev ต้องมีผลตรวจสภาพผ่านภายใน inspectionMaxAge
     */
    function recordTaxPayment(
        uint256 tokenId,
        uint16  taxYear,
        uint64  validUntil,
        bytes32 receiptHash
    ) external onlyRole(DLT_OFFICER_ROLE) vehicleExists(tokenId) {
        emit TaxPaid(tokenId, taxYear, uint64(block.timestamp), validUntil, receiptHash, TaxStatus.Paid);
    }

    // ─── Flags ───────────────────────────────────────────────
    /**
     * @notice ตั้ง/ปิด flag เช่น stolen, seized, flood, totalLoss
     */
    function setFlag(
        uint256 tokenId,
        uint64  flagBit,
        bool    active,
        bytes32 refHash
    ) external onlyRole(DLT_OFFICER_ROLE) vehicleExists(tokenId) {
        _setFlag(tokenId, flagBit, active, refHash);

        // ถ้าตั้ง stolen/seized/totalLoss → ล็อกการโอนอัตโนมัติ
        if (active && (flagBit == FLAG_STOLEN || flagBit == FLAG_SEIZED || flagBit == FLAG_TOTAL_LOSS)) {
            vehicleNFT.setTransferLock(tokenId, true);
        }
    }

    function _setFlag(uint256 tokenId, uint64 flagBit, bool active, bytes32 refHash) internal {
        if (active) {
            flags[tokenId] |= flagBit;
        } else {
            flags[tokenId] &= ~flagBit;
        }
        emit FlagUpdated(tokenId, flags[tokenId], msg.sender, refHash);
    }

    // ─── Inspection ──────────────────────────────────────────
    /**
     * @notice บันทึกผลตรวจสภาพ (ตรอ.)
     */
    function recordInspection(
        uint256 tokenId,
        uint8   result,       // 0 = fail, 1 = pass
        bytes32 metricsHash,
        bytes32 certHash
    ) external onlyRole(INSPECTOR_ROLE) vehicleExists(tokenId) {
        uint64 issuedAt = uint64(block.timestamp);

        if (result == 1) {
            lastInspectionPassAt[tokenId] = issuedAt;
        }

        emit InspectionRecorded(tokenId, msg.sender, result, metricsHash, certHash, issuedAt);
    }

    // ─── Admin ───────────────────────────────────────────────
    function setInspectionMaxAge(uint64 _maxAge) external onlyRole(DEFAULT_ADMIN_ROLE) {
        inspectionMaxAge = _maxAge;
    }

    // ─── View ────────────────────────────────────────────────
    function getRegistration(uint256 tokenId) external view returns (RegistrationData memory) {
        return registrations[tokenId];
    }

    function getFlags(uint256 tokenId) external view returns (uint64) {
        return flags[tokenId];
    }

    function hasFlag(uint256 tokenId, uint64 flagBit) external view returns (bool) {
        return (flags[tokenId] & flagBit) != 0;
    }
}

